<div class="page-actions"><div><p class="muted">Riwayat barang masuk dan keluar dari Purchase/Sales Order.</p></div><a class="btn" href="?page=stock">← Kembali ke Stok</a></div>
<div class="card filter-card"><form class="filter-grid" method="get"><input type="hidden" name="page" value="movements"><select name="product_id"><option value="">Semua produk</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=$filters['product_id']==$p['id']?'selected':''?>><?=e($p['code'].' - '.$p['name'])?></option><?php endforeach;?></select><select name="warehouse_id"><option value="">Semua gudang</option><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>" <?=$filters['warehouse_id']==$w['id']?'selected':''?>><?=e($w['name'])?></option><?php endforeach;?></select><button class="btn btn-primary">Filter</button><a class="btn" href="?page=movements">Reset</a></form></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Tipe</th><th>Nomor Transaksi</th><th>Produk</th><th>Gudang</th><th>Qty</th></tr></thead><tbody><?php foreach($result['items'] as $r):?><tr><td><?=e($r['movement_date'])?></td><td><span class="badge <?=$r['transaction_type']==='IN'?'status-active':'priority-medium'?>"><?=e($r['transaction_type'])?></span></td><td><?=e($r['transaction_number'])?></td><td><?=e($r['product_code'].' - '.$r['product_name'])?></td><td><?=e($r['warehouse_name'])?></td><td><?=number_format((float)$r['qty'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$result['items']):?><tr><td colspan="6" class="empty">Belum ada movement.</td></tr><?php endif;?></tbody></table></div><?=paginationLinks($result,['page'=>'movements','product_id'=>$filters['product_id'],'warehouse_id'=>$filters['warehouse_id']])?></div>
